sys_script.script:
(function riskEscalation(current, previous) {
    var needsIntervention = current.getValue('u_needs_intervention') == 'true' || current.getValue('u_needs_intervention') == '1';
    var sentimentScore = parseInt(current.getValue('u_sentiment_score'), 10);

    // Only escalate if intervention requested or sentiment is low
    if (!needsIntervention && (isNaN(sentimentScore) || sentimentScore > 2)) {
        return;
    }

    var retCaseId = current.getValue('u_retention_case');
    if (!retCaseId) {
        return;
    }

    // 1. Determine risk level
    var riskLevel = 'low';
    if (!isNaN(sentimentScore) && sentimentScore <= 1) {
        riskLevel = 'critical';
    } else if (!isNaN(sentimentScore) && sentimentScore <= 2) {
        riskLevel = 'high';
    } else if (needsIntervention) {
        riskLevel = 'medium';
    }

    // 2. Create Risk Alert
    var alert = new GlideRecord('x_2023506_german_1_ret_risk');
    alert.initialize();
    alert.setValue('u_retention_case', retCaseId);
    alert.setValue('u_triggering_checkin', current.getUniqueValue());
    alert.setValue('u_risk_level', riskLevel);
    alert.setValue('u_status', 'new');
    alert.setValue('u_issue_summary', current.getValue('u_settling_feedback') || 'No feedback provided');
    alert.insert();

    // 3. Update parent Retention Case status
    var retCase = new GlideRecord('x_2023506_german_1_ret_case');
    if (retCase.get(retCaseId)) {
        if (!isNaN(sentimentScore) && sentimentScore <= 2) {
            retCase.setValue('u_retention_status', 'critical_risk');
        } else if (needsIntervention) {
            retCase.setValue('u_retention_status', 'needs_attention');
        }

        // 4. Add work notes about the escalation
        var milestone = current.getDisplayValue('u_milestone');
        var note = 'Risk Alert escalated from ' + milestone + ' check-in. ' +
            'Risk Level: ' + riskLevel.charAt(0).toUpperCase() + riskLevel.slice(1) + '. ' +
            'Sentiment Score: ' + (isNaN(sentimentScore) ? 'N/A' : sentimentScore) + '/5. ' +
            'Intervention Requested: ' + (needsIntervention ? 'Yes' : 'No') + '.';

        retCase.work_notes = note;
        retCase.update();
    }
})(current, previous);
